CREATE TABLE IF NOT EXISTS guides(id TEXT PRIMARY KEY,guide_number INTEGER NOT NULL UNIQUE,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,parent_id TEXT,branch TEXT,sort_order INTEGER NOT NULL DEFAULT 0,content TEXT NOT NULL DEFAULT '',content_version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS guide_choices(id TEXT PRIMARY KEY,from_guide_id TEXT NOT NULL,choice_text TEXT NOT NULL,to_guide_id TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(from_guide_id) REFERENCES guides(id),FOREIGN KEY(to_guide_id) REFERENCES guides(id));
CREATE TABLE IF NOT EXISTS user_guide_state(user_id TEXT NOT NULL,guide_id TEXT NOT NULL,viewed_at TEXT,bookmarked INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,guide_id));
CREATE TABLE IF NOT EXISTS questionnaires(id TEXT PRIMARY KEY,version TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS questions(id TEXT PRIMARY KEY,questionnaire_id TEXT NOT NULL,position INTEGER NOT NULL,text TEXT NOT NULL,FOREIGN KEY(questionnaire_id) REFERENCES questionnaires(id));
CREATE TABLE IF NOT EXISTS answer_options(id TEXT PRIMARY KEY,question_id TEXT NOT NULL,position INTEGER NOT NULL,text TEXT NOT NULL,decision_values TEXT,FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE IF NOT EXISTS quiz_attempts(id TEXT PRIMARY KEY,user_id TEXT,questionnaire_version TEXT NOT NULL,engine_version TEXT NOT NULL,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT,is_current INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS quiz_answers(attempt_id TEXT NOT NULL,question_id TEXT NOT NULL,answer_id TEXT NOT NULL,PRIMARY KEY(attempt_id,question_id));
CREATE TABLE IF NOT EXISTS quiz_results(id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL UNIQUE,business_shape TEXT,implementation_direction TEXT,confidence TEXT,explanation TEXT,tradeoffs TEXT,unresolved_questions TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS result_recommendations(result_id TEXT NOT NULL,guide_id TEXT NOT NULL,recommendation_type TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(result_id,guide_id));